function updateFormula(){const m=MODELS[model];$('pde-formula').innerHTML={cubic:'u<sub>t</sub> + (315/8)u²u<sub>x</sub> + (71/4)u<sub>xx</sub> − (15/2)u<sub>xxx</sub> + u<sub>xxxx</sub> = 0',burgers:'u<sub>t</sub> + uu<sub>x</sub> = ½u<sub>xx</sub>',kdvb:'u<sub>t</sub> − 12uu<sub>x</sub> − 5u<sub>xx</sub> + u<sub>xxx</sub> = 0'}[model];$('formula-type').textContent=`Order ${m.order} · ${m.left} → ${m.right}`;$('boundary-label').textContent=m.order===4?'w = wξ = 0 at ξ = ±L. Clamped finite interval.':m.order===2?'w = 0 at ξ = ±L. Dirichlet finite interval.':'Analytic translation only; third-order boundary evolution is not implemented.';}
function configFromUI(){const cfg={...DEFAULTS,model,mode:$('mode').value};for(const id of ['amplitude','k','center','width','T','L','N','dt'])cfg[id]=Number($(id).value);return validateConfig(cfg);}
function applyConfig(cfg){model=cfg.model;$$('.model-tab').forEach(b=>b.classList.toggle('selected',b.dataset.model===model));for(const id of ['amplitude','k','center','width','T','L','N','dt','mode']){if(id==='N'&&!Array.from($('N').options).some(o=>o.value===String(cfg.N))){const o=new Option(String(cfg.N),String(cfg.N));$('N').add(o);}$(id).value=cfg[id];}for(const opt of $('mode').options)opt.disabled=model==='kdvb'&&opt.value!=='exact';updateFormula();}
function chooseModel(id,run=true){const cfg={...DEFAULTS,model:id};if(id==='burgers')Object.assign(cfg,{T:4,dt:.002,k:1,center:-2,width:1.5,amplitude:.03});if(id==='kdvb')Object.assign(cfg,{mode:'exact',T:3,amplitude:0,center:0,k:0});applyConfig(cfg);coordinate=id==='kdvb'?'lab':'moving';updateCoordinate();if(run)runExperiment();}
function setBusy(busy){$('run').disabled=busy;$('cancel').classList.toggle('hidden',!busy);$('progress').style.display=busy?'block':'none';$('run-state').innerHTML=`<i></i>${escapeHTML(busy?'Computing':'Computed')}`;}
function runExperiment(){let cfg;try{cfg=configFromUI();}catch(e){toast(e.message);return;}pause();if(worker)worker.terminate();worker=new Worker(new URL('./worker.js',import.meta.url),{type:'module'});setBusy(true);$('control-status').textContent='Running in a dedicated worker…';$('progress').firstElementChild.style.width='0';const runWorker=worker;worker.onmessage=({data})=>{if(runWorker!==worker)return;if(data.type==='progress'){$('progress').firstElementChild.style.width=`${data.progress*100}%`;return;}if(data.type==='error'){setBusy(false);$('control-status').textContent=data.message;$('run-state').textContent='Run failed';toast(data.message);worker.terminate();worker=null;return;}result=data.result;result.createdAt=new Date().toISOString();frame=0;setBusy(false);worker.terminate();worker=null;$('timeline').max=result.frames.length-1;$('timeline').value=0;$('control-status').textContent=`${result.steps.toLocaleString('en-GB')} steps · ${Math.round(result.elapsedMs)} ms · Δt=${fmt(result.dt,6)}`;history.unshift({at:result.createdAt,config:result.config});history=history.slice(0,12);try{localStorage.setItem('phaseatlas-history',JSON.stringify(history));}catch{}renderAll();updateEvidence();renderHistory();if(view==='lab'&&!matchMedia('(prefers-reduced-motion: reduce)').matches)play();};worker.onerror=e=>{setBusy(false);toast(`Worker error: ${e.message}`);worker?.terminate();worker=null;};worker.postMessage({type:'simulate',config:cfg});}
