function play(){if(!result)return;if(frame>=result.frames.length-1)frame=0;playing=true;$('play').textContent='Ⅱ';playStart=performance.now();playStartFrame=frame;const tick=now=>{if(!playing)return;const speed=Number($('speed').value);frame=Math.max(0,Math.min(result.frames.length-1,playStartFrame+Math.floor((now-playStart)/12000*speed*(result.frames.length-1))));renderFrame();if(frame>=result.frames.length-1){pause();return;}raf=requestAnimationFrame(tick);};raf=requestAnimationFrame(tick);}
function updateCoordinate(){$('coordinate-moving').classList.toggle('selected',coordinate==='moving');$('coordinate-lab').classList.toggle('selected',coordinate==='lab');if(result)renderFrame();}
const plotCache=new Map();
function canvasSetup(canvas){const rect=canvas.getBoundingClientRect();const w=Math.max(180,rect.width||600),h=Math.max(80,rect.height||240),dpr=Math.min(devicePixelRatio||1,2);if(canvas.width!==Math.round(w*dpr)||canvas.height!==Math.round(h*dpr)){canvas.width=Math.round(w*dpr);canvas.height=Math.round(h*dpr);}const ctx=canvas.getContext('2d');ctx.setTransform(dpr,0,0,dpr,0,0);ctx.clearRect(0,0,w,h);return {ctx,w,h};}
function tickLabel(v){return v===0?'0':Math.abs(v)>=1000||Math.abs(v)<.001?v.toExponential(0):Math.abs(v)<1?v.toFixed(2).replace(/0$/,''):v.toFixed(1).replace(/\.0$/,'');}
function drawPlot(canvas,series,opt={}){const {ctx,w,h}=canvasSetup(canvas);const pad={l:48,r:16,t:17,b:32};let {xmin,xmax,ymin,ymax}=opt;if(xmin===undefined)xmin=Math.min(...series.map(s=>Math.min(...s.x)));if(xmax===undefined)xmax=Math.max(...series.map(s=>Math.max(...s.x)));if(ymin===undefined)ymin=Math.min(...series.flatMap(s=>s.y));if(ymax===undefined)ymax=Math.max(...series.flatMap(s=>s.y));if(!Number.isFinite(ymin)||!Number.isFinite(ymax)){ymin=-1;ymax=1;}if(ymax-ymin<1e-15){ymin-=1;ymax+=1;}const X=x=>pad.l+(x-xmin)/(xmax-xmin)*(w-pad.l-pad.r),Y=y=>h-pad.b-(y-ymin)/(ymax-ymin)*(h-pad.t-pad.b);ctx.fillStyle='#fff';ctx.fillRect(0,0,w,h);ctx.lineWidth=1;ctx.font='9px Arial, Helvetica';ctx.fillStyle='#65718a';for(let i=0;i<=4;i++){const y=ymin+(ymax-ymin)*i/4;ctx.strokeStyle='#edf0f5';ctx.beginPath();ctx.moveTo(pad.l,Y(y));ctx.lineTo(w-pad.r,Y(y));ctx.stroke();ctx.textAlign='right';ctx.fillText(opt.log?`10${superscript(Math.round(y))}`:tickLabel(y),pad.l-9,Y(y)+3);const x=xmin+(xmax-xmin)*i/4;ctx.textAlign='center';ctx.fillText(tickLabel(x),X(x),h-pad.b+16);}if(ymin<0&&ymax>0){ctx.strokeStyle='#d7dce7';ctx.beginPath();ctx.moveTo(pad.l,Y(0));ctx.lineTo(w-pad.r,Y(0));ctx.stroke();}if(opt.window){ctx.fillStyle='#0000cd08';ctx.fillRect(X(opt.window[0]),pad.t,X(opt.window[1])-X(opt.window[0]),h-pad.t-pad.b);}ctx.save();ctx.beginPath();ctx.rect(pad.l,pad.t,w-pad.l-pad.r,h-pad.t-pad.b);ctx.clip();for(const s of series){ctx.strokeStyle=s.color||COLORS.teal;ctx.lineWidth=s.width||1.8;ctx.setLineDash(s.dashed?[5,4]:[]);ctx.beginPath();for(let i=0;i<s.x.length;i++){if(i===0)ctx.moveTo(X(s.x[i]),Y(s.y[i]));else ctx.lineTo(X(s.x[i]),Y(s.y[i]));}ctx.stroke();}if(opt.cursor!==undefined){ctx.strokeStyle='#5555a070';ctx.setLineDash([3,4]);ctx.beginPath();ctx.moveTo(X(opt.cursor),pad.t);ctx.lineTo(X(opt.cursor),h-pad.b);ctx.stroke();}ctx.restore();ctx.setLineDash([]);ctx.fillStyle='#65718a';ctx.font='10px Arial, Helvetica';ctx.textAlign='right';ctx.fillText(opt.xlabel||'ξ',w-pad.r,h-2);ctx.textAlign='left';ctx.fillText(opt.ylabel||'',pad.l,10);if(opt.message){ctx.textAlign='center';ctx.fillText(opt.message,w/2,h/2);}plotCache.set(canvas.id,{series,opt:{...opt,xmin,xmax,ymin,ymax},w,h});return {X,Y,pad,w,h};}
function superscript(n){const map={'-':'⁻','0':'⁰','1':'¹','2':'²','3':'³','4':'⁴','5':'⁵','6':'⁶','7':'⁷','8':'⁸','9':'⁹'};return String(n).split('').map(x=>map[x]).join('');}
function sample(array,x,cfg){const j=(x+cfg.L)/(2*cfg.L)*(cfg.N-1);if(j<0||j>cfg.N-1)return 0;const i=Math.floor(j),a=j-i;return array[i]*(1-a)+(array[Math.min(i+1,cfg.N-1)]||0)*a;}
function currentSeries(data=result,index=frame,coord=coordinate){const f=data.frames[index],m=MODELS[data.config.model],x=data.x,shift=coord==='lab'?m.c*f.t:0,ref=x.map(z=>profile(z-shift,data.config.model)),w=coord==='lab'?x.map(z=>sample(f.w,z-shift,data.config)):f.w;return {x,ref,w,u:ref.map((v,i)=>v+w[i])};}
function renderFrame(){if(!result)return;const f=result.frames[frame],cfg=result.config,m=MODELS[cfg.model],s=currentSeries(),maxPeak=Math.max(...result.frames.map(f=>f.diag.peak)),pertScale=Math.max(maxPeak*1.1,1e-6);$('timeline').value=frame;$('frame-label').textContent=`${frame} / ${result.frames.length-1}`;$('metric-time').textContent=fmt(f.t,4);$('metric-efold').textContent=cfg.model==='cubic'?`${fmt(f.t*5041/64,2)} ${'growth times'}`:`c = ${m.c}`;$('metric-peak').textContent=fmt(f.diag.peak,5);const init=result.frames[0].diag;$('metric-local').textContent=init.local?fmt(f.diag.local/init.local,3):'—';$('metric-boundary').textContent=`${fmt(f.diag.boundary*100,4)}%`;$('metric-boundary').style.color=f.diag.boundary>1e-4?COLORS.orange:'';$('plot-description').innerHTML=profileFormula(cfg.model)+` · c = ${m.c}`;$('plot-mode-label').textContent=cfg.mode==='exact'?'Analytic · no numerical evolution':cfg.mode==='linear'?'Linearized evolution':'Nonlinear perturbation';if(view!=='lab')return;drawPlot($('wave-plot'),[{x:s.x,y:s.ref,color:COLORS.gray,dashed:true,width:1.5},{x:s.x,y:s.u,color:COLORS.teal,width:2.2}],{xmin:-cfg.L,xmax:cfg.L,ymin:Math.min(-.13,-maxPeak*1.1),ymax:Math.max(1.13,1+maxPeak*1.1),xlabel:coordinate==='lab'?'x = ξ + ct':'ξ = x − ct',ylabel:'u',window:coordinate==='moving'?[-5,5]:null});drawPlot($('perturbation-plot'),[{x:s.x,y:s.w,color:COLORS.orange}],{xmin:-cfg.L,xmax:cfg.L,ymin:-pertScale,ymax:pertScale,xlabel:coordinate==='lab'?'x':'ξ',ylabel:'w'});drawHeatmap();drawGrowth();}
let heatImage=null,heatSignature=null;
function heatColor(z){const a=Math.min(1,Math.abs(z)),from=[255,255,255],to=z<0?[0,0,205]:[201,100,40];return from.map((v,i)=>Math.round(v+(to[i]-v)*Math.sqrt(a)));}
function drawHeatmap(){const canvas=$('heatmap'),{ctx,w,h}=canvasSetup(canvas),pad={l:48,r:16,t:8,b:32},cfg=result.config,F=result.frames,eps=cfg.amplitude||1,max=Math.max(1e-9,...F.map(f=>f.diag.peak))/eps;if(heatSignature!==result){heatImage=document.createElement('canvas');heatImage.width=cfg.N;heatImage.height=F.length;const ic=heatImage.getContext('2d'),im=ic.createImageData(cfg.N,F.length);for(let r=0;r<F.length;r++)for(let j=0;j<cfg.N;j++){const k=((F.length-1-r)*cfg.N+j)*4,c=heatColor(F[r].w[j]/eps/max);im.data[k]=c[0];im.data[k+1]=c[1];im.data[k+2]=c[2];im.data[k+3]=255;}ic.putImageData(im,0,0);heatSignature=result;}ctx.drawImage(heatImage,pad.l,pad.t,w-pad.l-pad.r,h-pad.t-pad.b);ctx.font='9px Arial';ctx.fillStyle='#65718a';for(let i=0;i<=4;i++){ctx.textAlign='center';ctx.fillText(tickLabel(-cfg.L+2*cfg.L*i/4),pad.l+(w-pad.l-pad.r)*i/4,h-14);ctx.textAlign='right';ctx.fillText(fmt(F.at(-1).t*i/4,3),pad.l-8,h-pad.b-(h-pad.t-pad.b)*i/4+3);}ctx.textAlign='right';ctx.fillText('ξ',w-pad.r,h-1);ctx.textAlign='left';ctx.fillText('t',8,12);const yy=h-pad.b-(h-pad.t-pad.b)*F[frame].t/(F.at(-1).t||1);ctx.strokeStyle='#00008060';ctx.setLineDash([4,3]);ctx.beginPath();ctx.moveTo(pad.l,yy);ctx.lineTo(w-pad.r,yy);ctx.stroke();ctx.setLineDash([]);$('heat-min').textContent=`−${fmt(max,2)}`;$('heat-max').textContent=`+${fmt(max,2)}`;}
function drawGrowth(){const F=result.frames,init=F[0].diag,logRatio=(d,key)=>Math.log10(Math.max(1e-12,d[key]/(init[key]||1))),series=['global','local','weighted'].map((key,i)=>({x:F.map(f=>f.t),y:F.map(f=>logRatio(f.diag,key)),color:[COLORS.teal,COLORS.orange,COLORS.purple][i]}));const ys=series.flatMap(s=>s.y),isExact=result.config.mode==='exact';drawPlot($('growth-plot'),isExact?[]:series,{xmin:0,xmax:F.at(-1).t,ymin:isExact?-1:Math.max(-12,Math.floor(Math.min(0,...ys))),ymax:isExact?1:Math.max(1,Math.ceil(Math.max(...ys))),xlabel:'t',ylabel:'norm / initial',log:true,cursor:F[frame].t,message:isExact?'Analytic translation: no perturbation':undefined});}
function renderAll(){heatSignature=null;renderFrame();const notes=[...result.warnings];if(result.config.mode!=='exact')notes.push('Finite-interval experiment; local window |ξ|≤5. The weighted norm can amplify left-tail roundoff and does not by itself classify stability.');$('run-warnings').textContent=notes.join(' ');$('run-warnings').classList.toggle('visible',notes.length>0);}
function atlasParameters(){return {alpha:Number($('atlas-alpha').value),beta:Number($('atlas-beta').value),eta:Number($('atlas-eta').value)};}
let mapGeometry=null;
function updateAtlas(){const {alpha,beta,eta}=atlasParameters(),m={...MODELS.cubic,alpha,beta};$('alpha-value').textContent=fmt(alpha);$('beta-value').textContent=fmt(beta);$('eta-value').textContent=fmt(eta);const rate=Math.max(farfieldBound(m,eta,0).rate,farfieldBound(m,eta,1).rate),eb=energyBound(alpha,beta);$('atlas-rate').textContent=fmt(rate);$('atlas-rate').style.color=rate<0?COLORS.teal:COLORS.orange;$('atlas-rate-note').textContent='Constant-endstate spectrum only';$('atlas-energy').textContent=fmt(eb.upper);$('atlas-energy').style.color=eb.upper<0?COLORS.teal:COLORS.orange;$('atlas-translation').textContent=eta> -1.5&&eta<1?'Included':'Excluded';$('atlas-residual').textContent=fmt(verifyProfile('cubic',{alpha,beta}).max,4);if(view!=='atlas')return;const ks=Array.from({length:201},(_,i)=>i/40);drawPlot($('spectrum-plot'),[0,1].map((state,i)=>({x:ks,y:ks.map(k=>spectralPoint(k,m,eta,state).re),color:i?COLORS.orange:COLORS.teal})),{xmin:0,xmax:5,ymin:-100,ymax:Math.max(20,Math.ceil(rate/20)*20+20),xlabel:'wave number k',ylabel:'Re λ (lower tail clipped)'});drawAtlasMap(alpha,beta,eta);}
function drawAtlasMap(alpha,beta,eta){const {ctx,w,h}=canvasSetup($('atlas-map')),p={l:48,r:20,t:12,b:35},W=w-p.l-p.r,H=h-p.t-p.b,n=72;const maxRate=160;for(let i=0;i<n;i++)for(let j=0;j<n;j++){const a=-20+5*(i+.5)/n,b=-8.5+2*(j+.5)/n,m={...MODELS.cubic,alpha:a,beta:b},rate=Math.max(farfieldBound(m,eta,0).rate,farfieldBound(m,eta,1).rate);ctx.fillStyle=`rgb(${heatColor(rate/maxRate).join(',')})`;ctx.fillRect(p.l+i*W/n,p.t+(n-1-j)*H/n,Math.ceil(W/n)+.1,Math.ceil(H/n)+.1);}ctx.fillStyle='#65718a';ctx.font='9px Arial';for(let i=0;i<=4;i++){ctx.textAlign='center';ctx.fillText(fmt(-20+5*i/4,2),p.l+W*i/4,h-16);ctx.textAlign='right';ctx.fillText(fmt(-8.5+2*i/4,2),p.l-7,p.t+H-H*i/4+3);}ctx.textAlign='right';ctx.fillText('α',w-p.r,h-2);ctx.textAlign='left';ctx.fillText('β',10,12);const X=p.l+(alpha+20)/5*W,Y=p.t+H-(beta+8.5)/2*H;ctx.beginPath();ctx.arc(X,Y,5,0,2*Math.PI);ctx.fillStyle='#fff';ctx.fill();ctx.strokeStyle='#17233c';ctx.lineWidth=2;ctx.stroke();const rx=p.l+(-17.75+20)/5*W,ry=p.t+H-(-7.5+8.5)/2*H;ctx.strokeStyle='#17233c80';ctx.lineWidth=1;ctx.beginPath();ctx.moveTo(rx-4,ry);ctx.lineTo(rx+4,ry);ctx.moveTo(rx,ry-4);ctx.lineTo(rx,ry+4);ctx.stroke();ctx.font='9px Arial';ctx.fillStyle='#000080';ctx.textAlign='left';ctx.fillText('−160 ← 0 → +160',p.l+8,p.t+14);mapGeometry={p,W,H};}
function computeFront(){const {alpha,beta}=atlasParameters();atlasWorker?.terminate();atlasWorker=new Worker(new URL('./worker.js',import.meta.url),{type:'module'});$('continue-front').disabled=true;$('continuation-status').textContent='Computing a shooting candidate…';atlasWorker.onmessage=({data})=>{$('continue-front').disabled=false;atlasWorker.terminate();atlasWorker=null;if(data.type==='error'){toast(data.message);return;}continued=data.result;if(!continued.ok){$('continuation-status').textContent=continued.reason||'Tail tolerance not met; existence unresolved.';return;}renderContinuation();};atlasWorker.onerror=e=>{$('continue-front').disabled=false;toast(e.message);atlasWorker?.terminate();atlasWorker=null;};atlasWorker.postMessage({type:'continue',alpha,beta});}
function renderContinuation(){if(view!=='atlas')return;const x=Array.from({length:401},(_,i)=>-10+i*.05),s=[{x,y:x.map(v=>profile(v)),dashed:true,color:COLORS.gray}];if(continued?.ok){const p=continued.points;s.push({x:p.map(r=>r[0]),y:p.map(r=>r[1]),color:COLORS.teal});drawPlot($('phase-plot'),[{x:p.map(r=>r[1]),y:p.map(r=>r[2]),color:COLORS.orange}],{xmin:-.05,xmax:1.05,ymin:Math.min(-.02,...p.map(r=>r[2])),ymax:Math.max(.3,...p.map(r=>r[2]))*1.1,xlabel:'v',ylabel:'v′'});$('continuation-status').textContent=`Numerical candidate: α=${continued.alpha}, β=${continued.beta}; right root r=${fmt(continued.r,5)}; left-tail indicator=${fmt(continued.tail)}. RK4 h=0.003, right initialization offset 10⁻⁷. This indicator is not a full discretization error or existence proof.`;}else drawPlot($('phase-plot'),[{x:x.map(v=>profile(v)),y:x.map(v=>profile(v,'cubic',1)),color:COLORS.gray,dashed:true}],{xmin:-.05,xmax:1.05,ymin:0,ymax:.35,xlabel:'v',ylabel:'v′ · reference'});drawPlot($('continuation-plot'),s,{xmin:-10,xmax:10,ymin:-.1,ymax:1.1,xlabel:'ξ',ylabel:'v'});}
function resetVerify(){const id=$('verify-model').value,m=MODELS[id];$('verify-c').value=m.c;$('verify-beta').value=m.beta;$('verify-gamma').value=m.gamma;updateVerify();}
function updateVerify(){const id=$('verify-model').value,override={c:Number($('verify-c').value),beta:Number($('verify-beta').value),gamma:Number($('verify-gamma').value)};if(!Object.values(override).every(Number.isFinite))return;const r=verifyProfile(id,override);$('verify-formula').innerHTML=profileFormula(id);$('residual-max').textContent=fmt(r.max,5);$('residual-l2').textContent=fmt(r.l2,5);$('residual-badge').textContent=r.max<1e-10?'Near floating-point roundoff':'Nonzero residual';$('residual-badge').classList.toggle('amber',r.max>=1e-10);if(view==='verify'){const max=Math.max(1e-15,r.max*1.2);drawPlot($('residual-plot'),[{x:r.samples.map(p=>p[0]),y:r.samples.map(p=>p[1]),color:r.max<1e-10?COLORS.teal:COLORS.orange}],{xmin:-20,xmax:20,ymin:-max,ymax:max,xlabel:'ξ',ylabel:'R(ξ)'});}}
function updateEvidence(){if(!result)return;const c=result.config,rows=[['Model',MODELS[c.model].name],['Mode',c.mode],['Time',`T=${result.frames.at(-1).t}; ${result.steps} steps; Δt=${result.dt}`],['Domain',`[−${c.L}, ${c.L}]; N=${c.N}; h=${2*c.L/(c.N-1)}`],['Initial condition',`ε=${c.amplitude}; ξ₀=${c.center}; σ=${c.width}; k=${c.k}`],['Boundary',result.boundary||'Analytic whole-line profile'],['Method',result.method],['Version',`PhaseAtlas ${VERSION}`],['Computed',result.createdAt]];$('experiment-metadata').innerHTML=rows.map(([a,b])=>`<dt>${escapeHTML(a)}</dt><dd>${escapeHTML(b)}</dd>`).join('');$('evidence-mode').textContent=c.mode==='exact'?'ANALYTIC':'NUMERICAL';}
