function renderHistory(){$('history-list').innerHTML=history.length?history.map((r,i)=>`<div class="history-row"><div><strong>${escapeHTML(MODELS[r.config?.model]?.short||'Experiment')}</strong> · ${escapeHTML(r.config?.mode||'')}<br><small>T=${escapeHTML(r.config?.T)} · N=${escapeHTML(r.config?.N)} · ε=${escapeHTML(r.config?.amplitude)} · ${escapeHTML(new Date(r.at).toLocaleString('en-GB'))}</small></div><button class="button small" data-reproduce="${i}">${'Reproduce ↗'}</button></div>`).join(''):`<p class="helper">${'Run an experiment to save its parameters.'}</p>`;}
